insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'Ученическо състезание по програмиране CODE@BURGAS 2027', 'Ученическото състезание по програмиране CODE@BURGAS дава възможност на участниците да проверят подготовката си по информатика и уменията си да решават задачи по програмиране. Организатори: Бургаски свободен университет и Община Бургас. Участват ученици от 4. до 12. клас в три възрастови групи: A (10–12 клас), B (7–9 клас) и C (4–6 клас). Решенията се оценяват автоматично от платформата codeburgas.com. Следващото издание е на 22 май 2027 г.', null, 'https://codeburgas.com/', 'Бургас', false, 'school'::public.audience, '2027-05-22T00:00:00+03:00', null, null, 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://codeburgas.com/')
