insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'XXVI Национален есенен турнир по информатика „Джон Атанасов“ 2026', 'Национален турнир по информатика за ученици от 4. до 12. клас (учениците от 1. до 3. клас участват в група E). Организатори: МОН, РУО – София-град и 91. НЕГ „Проф. Константин Гълъбов“. Провежда се 27 – 29 ноември 2026 г. в София, във ФМИ на СУ „Св. Климент Охридски“ и НПМГ „Акад. Любомир Чакалов“; състезанието е в събота, 28 ноември, от 9:00 ч. Езикът е C++, задачите са алгоритмични, максимумът е 300 точки. Групи: A (11.–12. клас), B (9.–10.), C (7.–8.), D (6.), E (4.–5.). Срок за регистрация: 15 ноември 2026 г., чрез областните отговорници (за София-град – sofiacode.com). Първите три места получават грамоти от МОН, има и отделно класиране за момичетата.', null, 'https://91neg.bg/turnir-dzhon-atanasov-2026/', 'София', false, 'school'::public.audience, '2026-11-27T12:00:00+02:00', '2026-11-29T23:59:00+02:00', '2026-11-15T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://91neg.bg/turnir-dzhon-atanasov-2026/')
