insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'FIRST LEGO League Challenge – сезон BIOGLOW (Биосвят) 2026–2027', 'Състезание по роботика за отбори от ученици на възраст между 9 и 16 години. Екипите строят и програмират LEGO робот (LEGO Education SPIKE Prime), който изпълнява мисии в робо-игра, и разработват иновативен проект по темата на сезона – биоразнообразие и опазване на екосистемите. Отбор е от 4 до 10 ученици. Такса за тематичния комплект: от 519 € с ДДС за 1 отбор; участие в националния Фестивал на роботиката: 100 € с ДДС на отбор. Регистрация на отбори: до 20 октомври 2026 г. Работни сесии: октомври 2026 – април 2027. Регионални и училищни събития: март – май 2027. Фестивал на роботиката FIRST LEGO League в Бургас: 17–18 април 2027 г.', null, 'https://www.fll.bg/teams-registrationbioglow', 'Бургас', false, 'school'::public.audience, '2027-04-17T00:00:00+03:00', '2027-04-18T23:59:00+03:00', '2026-10-20T23:59:00+03:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.fll.bg/challenge')
