insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'Hack Smart Sofia 2026', 'Присъствен хакатон в Нов български университет за около 40 студенти (бакалаври, магистри и докторанти) от университетите в алианса ERUA, в международни и интердисциплинарни отбори, които решават реални градски предизвикателства (Smart City). Подготвителен етап: 15–16 юни – посещение в София Тех Парк. Хакатон в НБУ: 17–19 юни 2026 г. – проучване на проблема, прототип и MVP с дигитални, AI и no-code инструменти, тестване и представяне пред жури. Завършилите получават 3 ECTS кредита и/или сертификат.', null, 'https://citiesconf.nbu.bg/hack-smart-sofia/', 'София', false, 'university'::public.audience, '2026-06-15T00:00:00+03:00', '2026-06-19T23:59:00+03:00', null, 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://citiesconf.nbu.bg/hack-smart-sofia/')
