insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'LiberHack Edition 2 – хакатон „Технологии в полза на хората“, Бургас', '48-часов хакатон за младежи от 14 до 21 години: build, pitch, and ship – от идея до работещо демо. Провежда се от 27 до 29 ноември 2026 г. в Международния конгресен център Бургас, с подкрепата на Община Бургас; започва в петък от 16:00 ч. и приключва в неделя около 18:30 ч. Отбори от 2 до 6 участници – не само програмисти, а смесица от хора, които кодират, мислят за потребителите и разказват истории с данни. Няма ограничения за технологиите (web scraping, OSINT, криптография, frontend фреймворци); кодът се пише само по време на събитието и проектите са с open source лиценз. Оценяване: техническо майсторство и сигурност (30%), радикално критично мислене (30%), дизайн и достъпност (20%), презентация (20%). Ментори: разработчици, дизайнери, журналисти и граждански активисти. Награден фонд 1200 €: 600 €, 400 € и 200 € за първите три места; всеки участник получава сертификат. Участието е безплатно, включително храната и настаняването в IYC Бургас за участниците извън Бургас. Под 18 години е нужна декларация от родител. Регистрацията е отворена до 20 ноември 2026 г.', null, 'https://liberhack.org/', 'Бургас', false, 'both'::public.audience, '2026-11-27T16:00:00+02:00', '2026-11-29T18:30:00+02:00', '2026-11-20T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://liberhack.org/')
