insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'Национален литературен конкурс „Петя Дубарова“ 2026, Бургас', 'Национален литературен конкурс за млади автори от 8. до 12. клас, посветен на поетесата Петя Дубарова. Организатори: Община Бургас, Къща музей „Петя Дубарова“, МОН, НДД и РУО – Бургас. Включен е в Националния календар за изяви по интереси на МОН и в Програмата с мерки за закрила на деца с изявени дарби. Участието е анонимно, в две направления: поезия (до пет стихотворения) и проза (до три разказа, до 7 страници всеки), само непубликувани творби. Конкурсът се обявява през януари; творбите се изпращат до 31 март, напечатани в 4 екземпляра, до Къща музей „Петя Дубарова“, ул. „Гладстон“ 68, Бургас. Заключителният етап е през май в Бургас (за 2026 г. – 8 май). Награди: голяма награда, първо, второ и трето място за поезия и за проза, специални награди и до 10 поощрения; наградените творби се отпечатват в сборника „Петя.... Пристан зелен“. Класираните на първо, второ и трето място ученици до 18 години имат право да кандидатстват за стипендия по Наредбата за закрила на деца с изявени дарби.', null, 'https://ruo.mon.bg/sofia-grad/files/sites/2/2026/01/nlk-statut-2026.doc', 'Бургас', false, 'school'::public.audience, '2026-05-08T00:00:00+03:00', null, '2026-03-31T23:59:00+03:00', 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://ruo.mon.bg/sofia-grad/files/sites/2/2026/01/nlk-statut-2026.doc')
