insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'Inherit the Past. Code the Future. – хакатон, Свищов 2026', 'Хакатон на Стопанска академия „Д. А. Ценов“ в Свищов, част от алианса KreativEU, който съчетава изкуствен интелект, културно наследство, предприемачество и иновации: дигитални преживявания за древни крепости, AI аватари на български дарители, инструменти за устойчив туризъм. За студенти от всички специалности – икономика, изкуства, компютърни науки, инженерство, хуманитарни науки, бизнес и дизайн. Състезание за начално финансиране (seed funding). Провежда се 26–28 май 2026 г.; срок за регистрация: 30 април 2026 г.', null, 'https://www.uni-svishtov.bg/en/news/inherit-the-past-code-the-future-26-28-may-2026-svishtov-bulgaria', 'Свищов', false, 'university'::public.audience, '2026-05-26T00:00:00+03:00', '2026-05-28T23:59:00+03:00', '2026-04-30T23:59:00+03:00', 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.uni-svishtov.bg/en/news/inherit-the-past-code-the-future-26-28-may-2026-svishtov-bulgaria')
